package dataStructure;

import java.util.LinkedHashSet;

public class LinkedHashSetExp {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		//FirstCome FirstOut - LinkedHashSet
		
		LinkedHashSet<String> objLHS = new LinkedHashSet<String>();
		objLHS.add("FireFox");
		objLHS.add("Brave");
		objLHS.add("Edge");
		objLHS.add("Chrome");
		System.out.println("Displayed LinkedHashSet");
		System.out.println(objLHS);

	}

}
